private void btnGosterGizle_Click(object sender, EventArgs e)
{
    if (txtSifre.PasswordChar == '*')
    {
        txtSifre.PasswordChar = '\0'; // Yıldızı kaldır (Açık metin)
        btnGosterGizle.Text = "Şifreyi Gizle";
    }
    else
    {
        txtSifre.PasswordChar = '*'; // Tekrar yıldızla
        btnGosterGizle.Text = "Şifreyi Göster";
    }
}

private void btnKitle_Click(object sender, EventArgs e)
{
    // Giriş kutularını ve butonları dondur
    txtAjanKod.Enabled = false;
    txtSifre.Enabled = false;
    btnGosterGizle.Enabled = false;

    lblBaslik.Text = "SİSTEM KİLİTLENDİ - YETKİSİZ ERİŞİM!";
    lblBaslik.ForeColor = Color.Red;
    this.BackColor = Color.LightGray;
}
